251	    @Override
252	    @Transactional
253	    public void saveOwner(Owner owner) throws DataAccessException {
254	        boolean isNew = owner.isNew();
255	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
256	        // roll it forward to the next business day so it never lands on a weekend. Everything
257	        // derived from the registration date below must use this adjusted value.
258	        LocalDate registrationDate = toBusinessDay(
259	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
260	        owner.setRegistrationDate(registrationDate);
261	        // Whether this owner was accepted into an existing household because the request declared it
262	        // shares one (sharesHousehold). A declared member is deliberately not treated as a suspected
263	        // duplicate below.
264	        boolean declaredHouseholdMember = false;
265	        if (owner.isNew()) {
266	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
267	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
268	            // it automatically. It is part of the owner's identityKey, so it is resolved first.
269	            owner.setHouseholdId(computeHouseholdId(owner));
270	            // The household is keyed on (last name, postcode), so the members are the existing owners
271	            // sharing both with this owner.
272	            List<Owner> householdMembers = findHouseholdMembers(owner);
273	            // Size of the household after this create: the existing members plus this new owner.
274	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
275	            // A second owner in an existing household is the same household and is rejected as a
276	            // household duplicate, UNLESS the request declares (via sharesHousehold) that it genuinely
277	            // shares the household. sharesHousehold only bypasses this block; it no longer creates the
278	            // link, which is now derived from (last name, postcode).
279	            if (!householdMembers.isEmpty()) {
280	                if (!owner.isSharesHousehold()) {
281	                    throw new HouseholdDuplicateException(owner.getHouseholdId());
282	                }
283	                declaredHouseholdMember = true;
284	            }
285	        }
286	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
287	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
288	        // subsumes the former separate telephone, email and household checks.
289	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
290	            throw new DuplicateIdentityException(owner.getIdentityKey());
291	        }
292	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's last name and
293	        // postcode while carrying a different telephone. Still created, but flagged as a possible
294	        // duplicate pointing at the matching owner. A declared household member is not a suspected
295	        // duplicate, so it is never flagged.
296	        if (owner.isNew() && !declaredHouseholdMember) {
297	            Owner softMatch = findPossibleDuplicate(owner);
298	            if (softMatch != null) {
299	                owner.setPossibleDuplicate(true);
300	                owner.setPossibleDuplicateOf(softMatch.getId());
301	            }
302	        }
303	        if (owner.isNew()
304	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
305	            throw new CityOwnerLimitExceededException(owner.getCity());
306	        }
307	        if (owner.isNew()
308	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
309	            throw new DailyOwnerLimitExceededException(registrationDate);
310	        }
311	        if (owner.isNew() && owner.getCustomerCode() == null) {
312	            owner.setCustomerCode(generateCustomerCode(owner));
313	        }
314	        if (owner.isNew()) {
315	            owner.setNamesakeCount(countNamesakes(owner));
316	            owner.setBulkSignupWarning(
317	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
318	        }
319	        if (owner.getMembershipNumber() == null) {
320	            owner.setMembershipNumber(generateMembershipNumber(owner));
321	        }
322	        ownerRepository.save(owner);
323	        if (isNew) {
324	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} registrationDate={}",
325	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
326	                owner.getRegistrationDate());
327	        }
328	    }
329	
330	    /**
331	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
332	     * owner. The key consolidates telephone, email and household into one value, so two owners
333	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
334	     * the owner's {@code householdId} has been resolved, so its key is complete.
335	     */
336	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
337	        String identityKey = owner.getIdentityKey();
338	        return ownerRepository.findAll().stream()
339	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
340	    }
341	
342	    /**
343	     * Find an existing owner this (new) owner soft-matches against: one sharing the same last name
344	     * (compared case-insensitively with collapsed whitespace, like household matching) and the same
345	     * postcode, but carrying a different telephone. Returns the lowest-id such owner, or {@code null}
346	     * when the owner has no last name or postcode to match on, or nothing matches. The caller only
347	     * invokes this once the hard {@code identityKey} duplicate check has already passed.
348	     */
349	    private Owner findPossibleDuplicate(Owner owner) {
350	        String key = householdKey(owner);
351	        if (key == null) {
352	            return null;
353	        }
354	        String telephone = owner.getTelephone();
355	        return ownerRepository.findAll().stream()
356	            .filter(existing -> key.equals(householdKey(existing))
357	                && !Objects.equals(telephone, existing.getTelephone()))
358	            .min(Comparator.comparing(Owner::getId))
359	            .orElse(null);
360	    }
361	
362	    /**
363	     * Count the owners that already exist (before this create) sharing the same first name and last
364	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
365	     * unique among the existing owners.
366	     */
367	    private int countNamesakes(Owner owner) {
368	        String firstName = owner.getFirstName();
369	        String lastName = owner.getLastName();
370	        if (firstName == null || lastName == null) {
371	            return 0;
372	        }
373	        return (int) ownerRepository.findAll().stream()
374	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
375	                && lastName.equalsIgnoreCase(existing.getLastName()))
376	            .count();
377	    }
378	
379	    /**
380	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
381	     * last name and its postcode. Last names are compared case-insensitively with collapsed
382	     * whitespace; postcodes are compared exactly. This is the same keying used by
383	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
384	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
385	     * postcode to match on.
386	     */
387	    private List<Owner> findHouseholdMembers(Owner owner) {
388	        String key = householdKey(owner);
389	        if (key == null) {
390	            return List.of();
391	        }
392	        return ownerRepository.findAll().stream()
393	            .filter(existing -> key.equals(householdKey(existing)))
394	            .toList();
395	    }
396	
397	    /**
398	     * Compute an owner's deterministic {@code householdId}: the first 12 lower-case hex characters of
399	     * SHA-256 over the UTF-8 bytes of {@code normalizedLastName + '|' + postcode} (see
400	     * {@link #householdKey(Owner)}). Owners with the same last name and postcode therefore share the
401	     * same {@code householdId} automatically. Returns {@code null} when the owner has no last name or
402	     * postcode, so it does not belong to a shared household.
403	     */
404	    private String computeHouseholdId(Owner owner) {
405	        String key = householdKey(owner);
406	        return key == null ? null : sha256Hex(key, 6, false);
407	    }
408	
409	    /**
410	     * Build the owner's household key, {@code normalizedLastName + '|' + postcode}, the single value
411	     * that identifies a household. The last name is normalized case-insensitively with collapsed
412	     * whitespace (see {@link #normalizeHouseholdKey}) and the postcode is used exactly as stored.
413	     * Returns {@code null} when the owner has no last name or postcode to key on. This is the shared
414	     * basis for both {@link #computeHouseholdId(Owner)} and household membership matching, so the two
415	     * cannot drift apart.
416	     */
417	    private String householdKey(Owner owner) {
418	        String lastName = normalizeHouseholdKey(owner.getLastName());
419	        String postcode = owner.getPostcode();
420	        if (lastName == null || postcode == null || postcode.isBlank()) {
421	            return null;
422	        }
423	        return lastName + "|" + postcode;
424	    }
425	
426	    /**
427	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
428	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
429	     */
430	    private String normalizeHouseholdKey(String value) {
431	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
432	    }
433	
434	    /**
435	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
436	     * code resolved from the owner's postcode (falling back to the owner's city, else
437	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
438	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
439	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
440	     * derived from the owner's own attributes.
441	     */
442	    private String generateCustomerCode(Owner owner) {
443	        return PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
444	    }
445	
446	    /**
447	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
448	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
449	     * with the owner's last name.
450	     */
451	    private String customerHash(Owner owner) {
452	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
453	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
454	        return sha256Hex(telephone + lastName, 4, true);
455	    }
456	
457	    /**
458	     * Compute the leading hex of SHA-256 over the UTF-8 bytes of {@code input}: the first
459	     * {@code bytes} bytes of the digest rendered as {@code 2 * bytes} hex characters, upper-case when
460	     * {@code upperCase} is {@code true}, otherwise lower-case. Shared by the derived identifiers that
461	     * are built from a SHA-256 prefix (e.g. the household id and the customer-code hash), so the
462	     * digest handling and the "SHA-256 not available" error live in one place.
463	     */
464	    private String sha256Hex(String input, int bytes, boolean upperCase) {
465	        byte[] digest;
466	        try {
467	            digest = MessageDigest.getInstance("SHA-256")
468	                .digest(input.getBytes(StandardCharsets.UTF_8));
469	        } catch (NoSuchAlgorithmException e) {
470	            throw new IllegalStateException("SHA-256 is required but not available", e);
471	        }
472	        String format = upperCase ? "%02X" : "%02x";
473	        StringBuilder hex = new StringBuilder(bytes * 2);
474	        for (int i = 0; i < bytes; i++) {
475	            hex.append(String.format(format, digest[i]));
476	        }
477	        return hex.toString();
478	    }
479	
480	    /**
481	     * Count the owners that already exist (before this create) in the same city as {@code owner},
482	     * compared case-insensitively.
483	     */
484	    private long countOwnersInCity(Owner owner) {
485	        String city = owner.getCity();
486	        return ownerRepository.findAll().stream()
487	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
488	            .count();
489	    }
490	
491	    /**
492	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
493	     * on the given {@code date}. Used to enforce the per-day create cap.
494	     */
495	    private long countOwnersRegisteredOn(LocalDate date) {
496	        return ownerRepository.findAll().stream()
497	            .filter(existing -> date.equals(existing.getRegistrationDate()))
498	            .count();
499	    }
500	
501	    /**
502	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
503	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
504	     * are required to fall on a business day.
505	     */
506	    private LocalDate toBusinessDay(LocalDate date) {
507	        switch (date.getDayOfWeek()) {
508	            case SATURDAY:
509	                return date.plusDays(2);
510	            case SUNDAY:
511	                return date.plusDays(1);
512	            default:
513	                return date;
514	        }
515	    }
516	
517	    /**
518	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
519	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
520	     */
521	    private String generateMembershipNumber(Owner owner) {
522	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
523	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
524	    }
525	
526	    @Override
527	    @Transactional(readOnly = true)
528	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
529	        return ownerRepository.findByLastName(lastName);
530	    }
531	
532	    @Override
533	    @Transactional(readOnly = true)
534	    public Collection<Visit> findVisitsByPetId(int petId) {
535	        return visitRepository.findByPetId(petId);
536	    }
537	
538	    @Override
539	    @Transactional(readOnly = true)
540	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
541	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
542	    }
543	
544	    private <T> T findEntityById(Supplier<T> supplier) {
545	        try {
546	            return supplier.get();
547	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
548	            // Just ignore not found exceptions for Jdbc/Jpa realization
549	            return null;
550	        }
551	    }
552	
553	}
