18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.service.CityOwnerLimitExceededException;
34	import org.springframework.samples.petclinic.service.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.service.DuplicateIdentityException;
36	import org.springframework.samples.petclinic.service.HouseholdDuplicateException;
37	import org.springframework.security.access.AccessDeniedException;
38	import org.springframework.validation.BindingResult;
39	import org.springframework.validation.FieldError;
40	import org.springframework.web.bind.MethodArgumentNotValidException;
41	import org.springframework.web.bind.annotation.ControllerAdvice;
42	import org.springframework.web.bind.annotation.ExceptionHandler;
43	import org.springframework.web.bind.annotation.ResponseBody;
44	
45	/**
46	 * Global Exception handler for REST controllers.
47	 * <p>
48	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
49	 *
50	 * @author Vitaliy Fedoriv
51	 * @author Alexander Dudkin
52	 */
53	@ControllerAdvice
54	public class ExceptionControllerAdvice {
55	
56	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
57	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
58	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
59	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
60	
61	    /**
62	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
63	     * class.
64	     *
65	     * @param e     Object referring to the thrown exception.
66	     * @param status HTTP response status.
67	     * @param url URL request.
68	     */
69	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
70	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
71	        problemDetail.setType(URI.create(url.toString()));
72	        problemDetail.setTitle(e.getClass().getSimpleName());
73	        problemDetail.setDetail(detail);
74	        problemDetail.setProperty("timestamp", Instant.now());
75	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
76	        return problemDetail;
77	    }
78	
79	    /**
80	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
81	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
82	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
83	     * would catch it and report an authorization failure as a 500.
84	     *
85	     * @param e The {@link AccessDeniedException} to propagate
86	     * @throws AccessDeniedException always
87	     */
88	    @ExceptionHandler(AccessDeniedException.class)
89	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
90	        throw e;
91	    }
92	
93	    /**
94	     * Handles {@link DuplicateIdentityException}, raised by the service layer when a new owner's whole
95	     * derived {@code identityKey} (normalized telephone, email and householdId) equals an existing
96	     * owner's, by returning a 409 Conflict status. This single handler replaces the former separate
97	     * telephone, email and household duplicate handlers.
98	     *
99	     * @param e The {@link DuplicateIdentityException} to be handled
100	     * @param request {@link HttpServletRequest} object referring to the current request.
101	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
102	     */
103	    @ExceptionHandler(DuplicateIdentityException.class)
104	    @ResponseBody
105	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
106	        logger.warn("Duplicate identity at {} {}: {}",
107	            request.getMethod(),
108	            request.getRequestURI(),
109	            e.getMessage());
110	        HttpStatus status = HttpStatus.CONFLICT;
111	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
112	        return ResponseEntity.status(status).body(detail);
113	    }
114	
115	    /**
116	     * Handles {@link HouseholdDuplicateException}, raised by the service layer when a new owner falls
117	     * into an existing household (another owner shares its last name and postcode) without declaring,
118	     * via {@code sharesHousehold}, that it shares the household, by returning a 409 Conflict status.
119	     *
120	     * @param e The {@link HouseholdDuplicateException} to be handled
121	     * @param request {@link HttpServletRequest} object referring to the current request.
122	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
123	     */
124	    @ExceptionHandler(HouseholdDuplicateException.class)
125	    @ResponseBody
126	    public ResponseEntity<ProblemDetail> handleHouseholdDuplicateException(HouseholdDuplicateException e, HttpServletRequest request) {
127	        logger.warn("Household duplicate at {} {}: {}",
128	            request.getMethod(),
129	            request.getRequestURI(),
130	            e.getMessage());
131	        HttpStatus status = HttpStatus.CONFLICT;
132	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
133	        return ResponseEntity.status(status).body(detail);
134	    }
135	
136	    /**
137	     * Handles {@link CityOwnerLimitExceededException}, raised by the service layer when a new owner's
138	     * city already contains the maximum number of owners, by returning a 409 Conflict status.
139	     *
140	     * @param e The {@link CityOwnerLimitExceededException} to be handled
141	     * @param request {@link HttpServletRequest} object referring to the current request.
142	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
143	     */
144	    @ExceptionHandler(CityOwnerLimitExceededException.class)
145	    @ResponseBody
146	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
147	        logger.warn("City owner limit exceeded at {} {}: {}",
148	            request.getMethod(),
149	            request.getRequestURI(),
150	            e.getMessage());
151	        HttpStatus status = HttpStatus.CONFLICT;
152	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
153	        return ResponseEntity.status(status).body(detail);
154	    }
155	
156	    /**
157	     * Handles {@link DailyOwnerLimitExceededException}, raised by the service layer when the maximum
158	     * number of owners for the current day have already been registered, by returning a 429 Too Many
159	     * Requests status.
160	     *
161	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
162	     * @param request {@link HttpServletRequest} object referring to the current request.
163	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
164	     */
165	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
166	    @ResponseBody
167	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
168	        logger.warn("Daily owner limit exceeded at {} {}: {}",
169	            request.getMethod(),
170	            request.getRequestURI(),
171	            e.getMessage());
172	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
173	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
174	        return ResponseEntity.status(status).body(detail);
175	    }
176	
177	    /**
178	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
179	     *
180	     * @param e The {@link Exception} to be handled
181	     * @param request {@link HttpServletRequest} object referring to the current request.
182	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
183	     */
184	    @ExceptionHandler(Exception.class)
185	    @ResponseBody
186	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
187	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
188	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
189	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
195	     * method returns a 404 Not Found status if an entity does not exist.
196	     *
197	     * @param e The {@link DataIntegrityViolationException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
200	     */
201	    @ExceptionHandler(DataIntegrityViolationException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
204	        logger.warn("Data integrity violation at {} {}: {}",
205	            request.getMethod(),
206	            request.getRequestURI(),
207	            e.getMessage());
208	        logger.debug("Data integrity violation stacktrace", e);
209	        HttpStatus status = HttpStatus.NOT_FOUND;
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	    /**
215	     * Handles exception thrown by Bean Validation on controller methods parameters. The response
216	     * body carries an {@code errors} array naming each rejected field (e.g. a required field that
217	     * is missing or blank), alongside the detailed {@code schemaValidationErrors}.
218	     *
219	     * @param e The {@link MethodArgumentNotValidException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
222	     */
223	    @ExceptionHandler(MethodArgumentNotValidException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
226	        HttpStatus status = HttpStatus.BAD_REQUEST;
227	        BindingErrorsResponse errors = new BindingErrorsResponse();
228	        BindingResult bindingResult = e.getBindingResult();
229	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
230	        if (bindingResult.hasErrors()) {
231	            errors.addAllErrors(bindingResult);
232	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
233	                .map(FieldError::getField)
234	                .distinct()
235	                .toList();
236	            detail.setProperty("errors", invalidFields);
237	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
238	                .map(fieldError -> {
239	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
240	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
241	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
242	                        fieldError.getField(),
243	                        defaultMessage,
244	                        rejectedValue);
245	                    return new ValidationMessageDto(message)
246	                        .putAdditionalProperty("field", fieldError.getField())
247	                        .putAdditionalProperty("rejectedValue", rejectedValue)
248	                        .putAdditionalProperty("defaultMessage", defaultMessage);
249	                })
250	                .toList();
251	            logger.debug("Validation error at {} {}: {}",
252	                request.getMethod(),
253	                request.getRequestURI(),
254	                bindingResult.getFieldErrors());
255	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
256	            return ResponseEntity.status(status).body(detail);
257	        }
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	}
