3	import java.util.Set;
4	
5	import jakarta.validation.ConstraintValidator;
6	import jakarta.validation.ConstraintValidatorContext;
7	
8	/**
9	 * Validates that an email address's domain is not on the disposable-domain blocklist
10	 * (mailinator.com, tempmail.com, guerrillamail.com). The domain is the part after the
11	 * last {@code '@'}, compared case-insensitively against the blocklist to match the
12	 * lower-cased canonical form {@code OwnerMapper} stores. A {@code null} value is left to
13	 * {@code @Email}, and a value without an {@code '@'} (not a valid address) is left to
14	 * {@code @Email} as well.
15	 */
16	public class EmailDomainValidator implements ConstraintValidator<EmailDomainValidation, String> {
17	
18	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
19	        "mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    @Override
22	    public boolean isValid(String email, ConstraintValidatorContext context) {
23	        if (email == null) {
24	            return true;
25	        }
26	        int at = email.lastIndexOf('@');
27	        if (at < 0) {
28	            return true;
29	        }
30	        String domain = email.substring(at + 1).trim().toLowerCase();
31	        return !BLOCKED_DOMAINS.contains(domain);
32	    }
33	}
