16	package org.springframework.samples.petclinic.util;
17	
18	/**
19	 * Normalizes free-form telephone numbers into canonical <a
20	 * href="https://en.wikipedia.org/wiki/E.164">E.164</a> form (a leading {@code '+'} followed by
21	 * country code and national digits, e.g. {@code '+61412345678'}).
22	 *
23	 * <p>The rules, applied in order: strip spaces, dashes and brackets; keep an explicit leading
24	 * {@code '+'} and country code when present, otherwise assume country code {@code '+61'} and drop a
25	 * single leading {@code '0'} from the national digits; require 8 to 15 digits after the {@code '+'}.
26	 * In addition, the national-number length must match the country code for the countries we recognise:
27	 * {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP) requires
28	 * exactly 10. A value that cannot satisfy these rules has no valid E.164 form.
29	 *
30	 * <p>This is the single source of truth shared by the inbound {@code TelephoneValidation}
31	 * constraint (which rejects numbers with no valid E.164 form) and {@code OwnerMapper} (which stores
32	 * the E.164 string), so a value that validates is exactly one that normalizes.
33	 */
34	public final class TelephoneNormalizer {
35	
36	    private static final String DEFAULT_COUNTRY_CODE = "61";
37	
38	    /** Australia ({@code '+61'}): national numbers are exactly 9 digits. */
39	    private static final int AU_NATIONAL_LENGTH = 9;
40	
41	    /** NANP country code ({@code '+1'}): US/Canada/etc. */
42	    private static final String NANP_COUNTRY_CODE = "1";
43	
44	    /** NANP ({@code '+1'}): national numbers are exactly 10 digits. */
45	    private static final int NANP_NATIONAL_LENGTH = 10;
46	
47	    private TelephoneNormalizer() {
48	    }
49	
50	    /**
51	     * Convert a raw telephone number to its E.164 form, or return {@code null} when it has none.
52	     *
53	     * @param raw the inbound telephone number (may be {@code null})
54	     * @return the E.164 string (e.g. {@code '+61412345678'}), or {@code null} if {@code raw} is
55	     * {@code null} or cannot form a valid E.164 number
56	     */
57	    public static String toE164(String raw) {
58	        if (raw == null) {
59	            return null;
60	        }
61	        String trimmed = raw.trim();
62	        boolean hasCountryCode = trimmed.startsWith("+");
63	        String body = hasCountryCode ? trimmed.substring(1) : trimmed;
64	        String digits = body.replaceAll("[\\s()\\-]", "");
65	        if (digits.isEmpty() || !digits.matches("\\d+")) {
66	            return null;
67	        }
68	        String e164Digits;
69	        if (hasCountryCode) {
70	            e164Digits = digits;
71	        } else {
72	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
73	            e164Digits = DEFAULT_COUNTRY_CODE + national;
74	        }
75	        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
76	            return null;
77	        }
78	        if (!hasValidNationalLength(e164Digits)) {
79	            return null;
80	        }
81	        return "+" + e164Digits;
82	    }
83	
84	    /**
85	     * Format a stored E.164 number for humans: the {@code '+'} and country code, a space, then the
86	     * national digits grouped in threes separated by spaces, e.g. {@code '+61412345678'} becomes
87	     * {@code '+61 412 345 678'}. The country code is recognised for the countries we know
88	     * ({@code '+61'} Australia, {@code '+1'} NANP); any other value is returned unchanged.
89	     *
90	     * @param e164 a stored E.164 telephone (e.g. {@code '+61412345678'}), may be {@code null}
91	     * @return the human-formatted display string, or {@code null} when {@code e164} is {@code null}
92	     */
93	    public static String toDisplay(String e164) {
94	        if (e164 == null) {
95	            return null;
96	        }
97	        if (!e164.startsWith("+")) {
98	            return e164;
99	        }
100	        String digits = e164.substring(1);
101	        if (!digits.matches("\\d+")) {
102	            return e164;
103	        }
104	        String countryCode = countryCodeOf(digits);
105	        if (countryCode == null) {
106	            return e164;
107	        }
108	        String national = digits.substring(countryCode.length());
109	        StringBuilder sb = new StringBuilder("+").append(countryCode);
110	        for (int i = 0; i < national.length(); i += 3) {
111	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
112	        }
113	        return sb.toString();
114	    }
115	
116	    /**
117	     * Return the country code of the given E.164 digits (the part after the {@code '+'}) for the
118	     * countries we recognise ({@code '61'} then {@code '1'}), or {@code null} when none matches.
119	     */
120	    private static String countryCodeOf(String e164Digits) {
121	        if (e164Digits.startsWith(DEFAULT_COUNTRY_CODE)) {
122	            return DEFAULT_COUNTRY_CODE;
123	        }
124	        if (e164Digits.startsWith(NANP_COUNTRY_CODE)) {
125	            return NANP_COUNTRY_CODE;
126	        }
127	        return null;
128	    }
129	
130	    /**
131	     * Check that the national-number length matches the country code for the countries we recognise.
132	     * {@code '+61'} (Australia) requires 9 national digits and {@code '+1'} (NANP) requires 10; any
133	     * other country code is left to the generic 8-to-15 digit bound.
134	     */
135	    private static boolean hasValidNationalLength(String e164Digits) {
136	        if (e164Digits.startsWith(DEFAULT_COUNTRY_CODE)) {
137	            return nationalLength(e164Digits, DEFAULT_COUNTRY_CODE) == AU_NATIONAL_LENGTH;
138	        }
139	        if (e164Digits.startsWith(NANP_COUNTRY_CODE)) {
140	            return nationalLength(e164Digits, NANP_COUNTRY_CODE) == NANP_NATIONAL_LENGTH;
141	        }
142	        return true;
143	    }
144	
145	    /** National-digit count for {@code e164Digits}, i.e. its length minus the country code. */
146	    private static int nationalLength(String e164Digits, String countryCode) {
147	        return e164Digits.length() - countryCode.length();
148	    }
149	}
