16	package org.springframework.samples.petclinic.util;
17	
18	import java.util.Locale;
19	import java.util.Map;
20	
21	/**
22	 * Normalizes free-form postal addresses into a single canonical form so a value is stored,
23	 * returned and compared in exactly one shape.
24	 *
25	 * <p>The rules, applied in order: trim surrounding whitespace and collapse internal runs of
26	 * whitespace to a single space; upper-case; and expand common street-type abbreviations as whole
27	 * words ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). For example
28	 * {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}. A value that is blank after
29	 * trimming and collapsing has no canonical form.
30	 *
31	 * <p>This is the single source of truth shared by the inbound {@code AddressValidation} constraint
32	 * (which rejects an address that is blank after normalization), {@code OwnerMapper} (which stores
33	 * the normalized string) and the household comparisons in the service layer, so a value that
34	 * validates is exactly one that normalizes.
35	 */
36	public final class AddressNormalizer {
37	
38	    private static final Map<String, String> ABBREVIATIONS = Map.of(
39	        "ST", "STREET",
40	        "RD", "ROAD",
41	        "AVE", "AVENUE");
42	
43	    private AddressNormalizer() {
44	    }
45	
46	    /**
47	     * Convert a raw address to its canonical form, or return {@code null} when it has none.
48	     *
49	     * @param raw the inbound address (may be {@code null})
50	     * @return the normalized address (e.g. {@code '12 MAIN STREET'}), or {@code null} if {@code raw}
51	     * is {@code null} or is blank after trimming and collapsing whitespace
52	     */
53	    public static String normalize(String raw) {
54	        if (raw == null) {
55	            return null;
56	        }
57	        String collapsed = raw.trim().replaceAll("\\s+", " ");
58	        if (collapsed.isEmpty()) {
59	            return null;
60	        }
61	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
62	        StringBuilder normalized = new StringBuilder();
63	        for (int i = 0; i < tokens.length; i++) {
64	            if (i > 0) {
65	                normalized.append(' ');
66	            }
67	            normalized.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
68	        }
69	        return normalized.toString();
70	    }
71	}
